using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

/// <summary>
/// Shared evaluation configuration for telemetry, quality, and compare modes.
/// </summary>
public static class EvalConfiguration
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "results");

    public static ReportingConfiguration CreateTelemetryConfig()
    {
        return CreateConfig(includeQuality: false);
    }

    public static ReportingConfiguration CreateQualityConfig()
    {
        return CreateConfig(includeQuality: true);
    }

    public static ReportingConfiguration CreateCompareConfig(string label)
    {
        return CreateConfig(includeQuality: true, scenarioLabel: label);
    }

    private static ReportingConfiguration CreateConfig(
        bool includeQuality,
        string? scenarioLabel = null)
    {
        var evaluators = new List<IEvaluator>
        {
            new ResponseLengthEvaluator()
        };

        if (includeQuality)
        {
            evaluators.Add(new RelevanceTruthAndCompletenessEvaluator());
            evaluators.Add(new CoherenceEvaluator());
            evaluators.Add(new FluencyEvaluator());
        }

        var storage = new DiskBasedReportingStorage(StoragePath);

        var builder = new ReportingConfiguration.Builder(storage, evaluators);

        if (scenarioLabel is not null)
        {
            builder.WithScenarioLabel(scenarioLabel);
        }

        return builder.Build();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that chat responses are produced and metrics are captured.
/// </summary>
public class TelemetryEvalTests : IAsyncLifetime
{
    private ScenarioRun? _scenarioRun;
    private readonly ReportingConfiguration _config = EvalConfiguration.CreateTelemetryConfig();

    public async Task InitializeAsync()
    {
        _scenarioRun = await _config.CreateScenarioRunAsync(
            scenarioName: nameof(TelemetryEvalTests));
    }

    public async Task DisposeAsync()
    {
        if (_scenarioRun is not null)
        {
            await _scenarioRun.DisposeAsync();
        }
    }

    [Fact]
    public async Task Chat_Response_Is_Captured()
    {
        var chatClient = CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await _scenarioRun!.EvaluateAsync(messages, response);

        Assert.NotNull(response);
        Assert.NotEmpty(response.Text);
    }

    [Fact]
    public async Task Chat_Response_Length_Is_Measured()
    {
        var chatClient = CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain recursion in one sentence.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await _scenarioRun!.EvaluateAsync(messages, response);

        Assert.True(response.Text.Length > 0);
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT")
            ?? "gpt-4o-mini";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(deployment)
            .AsIChatClient();
    }
}

