using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same scenarios with different configurations
/// and stores results under distinct labels for side-by-side comparison.
/// </summary>
public class CompareEvalTests : IAsyncLifetime
{
    private ScenarioRun? _baselineRun;
    private ScenarioRun? _candidateRun;

    private readonly ReportingConfiguration _baselineConfig =
        EvalConfiguration.CreateCompareConfig("baseline");

    private readonly ReportingConfiguration _candidateConfig =
        EvalConfiguration.CreateCompareConfig("candidate");

    public async Task InitializeAsync()
    {
        _baselineRun = await _baselineConfig.CreateScenarioRunAsync(
            scenarioName: nameof(CompareEvalTests));
        _candidateRun = await _candidateConfig.CreateScenarioRunAsync(
            scenarioName: nameof(CompareEvalTests));
    }

    public async Task DisposeAsync()
    {
        if (_baselineRun is not null) await _baselineRun.DisposeAsync();
        if (_candidateRun is not null) await _candidateRun.DisposeAsync();
    }

    [Fact]
    public async Task Compare_Baseline_And_Candidate()
    {
        var prompt = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what a REST API is in simple terms.")
        };

        // Baseline: default temperature
        var baselineClient = CreateChatClient(temperature: 0.3f);
        var baselineResponse = await baselineClient.GetResponseAsync(prompt);
        await _baselineRun!.EvaluateAsync(prompt, baselineResponse);

        // Candidate: higher temperature
        var candidateClient = CreateChatClient(temperature: 0.9f);
        var candidateResponse = await candidateClient.GetResponseAsync(prompt);
        await _candidateRun!.EvaluateAsync(prompt, candidateResponse);

        // Both should produce valid responses; compare via reports
        Assert.NotEmpty(baselineResponse.Text);
        Assert.NotEmpty(candidateResponse.Text);
    }

    [Fact]
    public async Task Compare_SystemPrompt_Variants()
    {
        var userMessage = new ChatMessage(ChatRole.User, "What is dependency injection?");

        // Baseline: concise system prompt
        var baselineMessages = new List<ChatMessage>
        {
            new(ChatRole.System, "Be concise."),
            userMessage
        };

        // Candidate: detailed system prompt
        var candidateMessages = new List<ChatMessage>
        {
            new(ChatRole.System, "Provide a detailed explanation with examples."),
            userMessage
        };

        var client = CreateChatClient();

        var baselineResponse = await client.GetResponseAsync(baselineMessages);
        await _baselineRun!.EvaluateAsync(baselineMessages, baselineResponse);

        var candidateResponse = await client.GetResponseAsync(candidateMessages);
        await _candidateRun!.EvaluateAsync(candidateMessages, candidateResponse);

        Assert.NotEmpty(baselineResponse.Text);
        Assert.NotEmpty(candidateResponse.Text);
    }

    private static IChatClient CreateChatClient(float? temperature = null)
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT")
            ?? "gpt-4o-mini";

        IChatClient client = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(deployment)
            .AsIChatClient();

        if (temperature is not null)
        {
            client = new ChatClientBuilder(client)
                .UseChatOptions(new ChatOptions { Temperature = temperature })
                .Build();
        }

        return client;
    }
}

